head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.vListBzTpCd = "";
scwin.clickListBzDtlTpCd = "";
scwin.clickAdjReqProcsNo = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
// var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fn_GetPar, scwin.fn_SetPar;

// dialog 호출용 함수
// 발행기관목록관련

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vListBzTpCd = "200";
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        scwin.setBzProcsNo(row);
        // alert ( clickAdjReqProcsStatCd );
        if ("FUNC_ACPT" === colid) {
            let vAnswer = confirm('승인처리 하시겠습니까?');
            if (vAnswer === true) {
                LastJob = "승인";
                await scwin.trs("35");
            }
        } else if ("FUNC_RJCT" === colid) {
            let vAnswer = confirm('불가처리 하시겠습니까?');
            if (vAnswer === true) {
                LastJob = "불가";
                await scwin.trs("36");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40005.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40005.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40005.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.listSync();
        scwin.parentRefresh();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40005.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40005.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&LIST_INVSTG_BZ_TP_CD=" + scwin.vListBzTpCd;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/StockOptionDutyHold.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description 접수 또는 반려처리
 * @param {String} listProcsStatCd listProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(listProcsStatCd) {
    vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : "U",
    //     LIST_PROCS_STAT_CD : listProcsStatCd,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
    //     LIST_BZ_DTL_TP_CD : scwin.clickListBzDtlTpCd,
    //     PROCS_EMP_NO : js_emp_no,
    //     ADJ_REQ_PROCS_NO : scwin.clickAdjReqProcsNo
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/StockOptionDutyHold.do",
        ref : "dts_List",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.clickListBzDtlTpCd = dts_List.getCellData(Number(obj), "LIST_BZ_DTL_TP_CD");
    scwin.clickAdjReqProcsNo = dts_List.getCellData(Number(obj), "ADJ_REQ_PROCS_NO");
    // alert(clickListBzDtlTpCd);

};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
